patch_result.patch:
--- a/libsepol/src/optimize.c
+++ b/libsepol/src/optimize.c
@@ -200,6 +200,13 @@
 	if (!(entry->key.specified & (AVTAB_AV|AVTAB_XPERMS)))
 		return 0;

+	/* malformed policies may contain invalid type IDs */
+	if (entry->key.source_type == 0 || entry->key.target_type == 0)
+		return 0;
+	if (entry->key.source_type > tab->p->p_types.nprim ||
+	    entry->key.target_type > tab->p->p_types.nprim)
+		return 0;
+
 	s_idx = entry->key.source_type - 1;
 	t_idx = entry->key.target_type - 1;

args:
@@ -199,6 +199,14 @@ static int is_avrule_redundant(avtab_ptr_t entry, avtab_t *tab,
 	if (!(entry->key.specified & (AVTAB_AV|AVTAB_XPERMS)))
 		return 0;

+	/* malformed policies may contain invalid type IDs */
+	if (entry->key.source_type == 0 || entry->key.target_type == 0)
+		return 0;
+	if (entry->key.source_type > tab->p->p_types.nprim ||
+	    entry->key.target_type > tab->p->p_types.nprim)
+		return 0;
+
 	s_idx = entry->key.source_type - 1;
 	t_idx = entry->key.target_type - 1;
